<script>
 import {formatDate} from '$lib/date.js';
 import {onMount} from 'svelte';import {locale} from '$lib/i18n.js';import {goto} from '$app/navigation';import {listDevices,listSites,listProjects,listDeployments,listLogs} from '$lib/api.js';import {devices,notify,user} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';import Modal from '$lib/components/Modal.svelte';
 let loading=true,showAddModal=false,deviceLimit=1,allSites=[],allProjects=[],recentDeployments=[],activity=[];
 $: ru=$locale!=='en';
 onMount(async()=>{const [d,s,p,dep,logs]=await Promise.all([listDevices(),listSites(),listProjects(),listDeployments(),listLogs(8)]);if(d.ok){devices.set(d.data.devices||[]);deviceLimit=d.data.limit||1}else notify(d.error||'Не удалось загрузить устройства','error');if(s.ok)allSites=s.data.sites||[];if(p.ok)allProjects=p.data.projects||[];if(dep.ok)recentDeployments=(dep.data.deployments||[]).slice(0,5);if(logs.ok)activity=(logs.data.logs||[]).slice(0,6);loading=false});
 $: onlineCount=$devices.filter(x=>x.status==='online').length;$: runningSites=allSites.filter(x=>x.site?.status==='running').length;$: offlineCount=$devices.length-onlineCount;
 function openDevice(device){goto('/devices/'+device.id)}
</script>
<svelte:head><title>Overview · Yevqo</title></svelte:head>
<div class="welcome-row"><div><div class="eyebrow"><span class="eyebrow-line"></span> {ru?'01 / РАБОЧАЯ ОБЛАСТЬ':'01 / WORKSPACE'}</div><h1 class="page-title">{ru?'Единый интерфейс. Вся твоя инфраструктура.':'One interface. Your entire infrastructure.'}</h1><p class="page-desc">{ru?'Управляй проектами, устройствами и развёртываниями из одного места.':'Manage projects, devices and deployments from one place.'}</p></div><Button variant="primary" on:click={()=>{$devices.length>=deviceLimit?goto('/devices'):showAddModal=true}}>{$devices.length>=deviceLimit?(ru?'Лимит устройств достигнут':'Device limit reached'):(ru?'＋ Добавить устройство':'＋ Add device')}</Button></div>
{#if loading}<div class="empty">{ru?'Загружаем инфраструктуру…':'Loading infrastructure…'}</div>{:else}
<div class="overview-grid">
 <div class="hero-panel"><div class="hero-orb orb-one"></div><div class="hero-orb orb-two"></div><div class="hero-content"><span class="hero-kicker">ANDROID + TERMUX</span><h2>{ru?'Инфраструктура Yevqo':'Yevqo infrastructure'}</h2><p>{ru?'Управляй устройствами, сайтами и базами данных из единой панели.':'Manage devices, sites and databases from one control panel.'}</p><div class="hero-status"><i></i> {$devices.length} {ru?'устройств':'devices'} <span>·</span> {onlineCount} {ru?'онлайн':'online'}</div></div><div class="hero-graphic"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="core-mark">V</div><span class="node node-a">⌘</span><span class="node node-b">◈</span><span class="node node-c">▣</span></div></div>
 <div class="quick-panel"><div class="panel-topline"><span>{ru?'БЫСТРЫЙ ДОСТУП':'QUICK ACCESS'}</span><span class="panel-dots">•••</span></div><a href="/databases" class="quick-link"><span class="quick-icon violet">◈</span><span><strong>{ru?'Серверы БД':'Database servers'}</strong><small>{ru?'Серверы и базы данных':'Servers and databases'}</small></span><b>↗</b></a><a href="/sites" class="quick-link"><span class="quick-icon cyan">◉</span><span><strong>{ru?'Сайты':'Websites'}</strong><small>{ru?'Размещённые приложения':'Hosted applications'}</small></span><b>↗</b></a><a href="/monitoring" class="quick-link"><span class="quick-icon green">⌁</span><span><strong>{ru?'Мониторинг':'Monitoring'}</strong><small>{ru?'Состояние инфраструктуры':'Infrastructure health'}</small></span><b>↗</b></a><a href="/deployments" class="quick-link"><span class="quick-icon amber">⇧</span><span><strong>{ru?'Развёртывания':'Deployments'}</strong><small>{ru?'История и процессы запуска':'Deployment history and operations'}</small></span><b>↗</b></a></div>
</div>
<div class="metrics-grid">
 <div class="metric-card"><div class="metric-top"><span>Проекты</span><span class="metric-icon">▦</span></div><div class="metric-value">{allProjects.length}</div><div class="metric-foot">{ru?'Созданные рабочие проекты':'Created workspace projects'}</div></div>
 <div class="metric-card"><div class="metric-top"><span>{ru?'Подключённые устройства':'Connected devices'}</span><span class="metric-icon">▣</span></div><div class="metric-value">{onlineCount}<small> / {devices.length}</small></div><div class="metric-foot">{offlineCount} офлайн · {deviceLimit} в тарифе</div></div>
 <div class="metric-card"><div class="metric-top"><span>{ru?'Активные развёртывания':'Active deployments'}</span><span class="metric-icon">↗</span></div><div class="metric-value">—</div><div class="metric-foot">{ru?'Backend пока не предоставляет активные jobs':'Active deployment jobs are not exposed by the backend yet'}</div></div>
 <div class="metric-card"><div class="metric-top"><span>{ru?'Состояние инфраструктуры':'Infrastructure health'}</span><span class="metric-icon green">●</span></div><div class="metric-value">{devices.length===0?'—':onlineCount===devices.length?'Online':onlineCount>0?'Partial':'Offline'}</div><div class="metric-foot">{runningSites} {ru?'работающих приложений':'running applications'}</div></div>
</div>
<div class="section-header"><div><h2 class="section-title">Проекты</h2><p class="section-subtitle">{ru?'Рабочие области и связанные ресурсы':'Workspaces and linked resources'}</p></div><a href="/projects" class="view-link">{ru?'Все проекты':'All projects'} <span>→</span></a></div>
{#if allProjects.length===0}<div class="empty compact-empty">{ru?'Проекты ещё не созданы.':'No projects created yet.'} <a href="/projects">{ru?'Создать проект →':'Create project →'}</a></div>{:else}<div class="sites-table-wrap"><table class="sites-table"><thead><tr><th>{ru?'ПРОЕКТ':'PROJECT'}</th><th>{ru?'УСТРОЙСТВА':'DEVICES'}</th><th>{ru?'ПРИЛОЖЕНИЯ':'APPS'}</th><th></th></tr></thead><tbody>{#each allProjects.slice(0,5) as project (project.id)}<tr><td><a href={'/projects/'+project.id}><strong>{project.name}</strong></a></td><td>{project.device_count||0}</td><td>{project.site_count||0}</td><td><a href={'/projects/'+project.id}>{ru?'Открыть →':'Open →'}</a></td></tr>{/each}</tbody></table></div>{/if}
<div class="section-header"><div><h2 class="section-title">{ru?'Ваши устройства':'Your devices'}</h2><p class="section-subtitle">{ru?'Подключённые хосты и их текущее состояние':'Connected hosts and their current status'}</p></div><a href="/devices" class="view-link">{ru?'Все устройства':'All devices'} <span>→</span></a></div>
{#if $devices.length===0}<div class="empty"><div class="empty-symbol">▣</div><h3>{ru?'Пока нет подключённых устройств':'No devices connected yet'}</h3><p class="empty-hint">{ru?'Установи Yevqo Agent в Termux, чтобы добавить первое устройство.':'Install Yevqo Agent in Termux to connect your first device.'}</p><div class="empty-action"><Button variant="primary" on:click={()=>showAddModal=true}>{ru?'Подключить устройство':'Connect device'}</Button></div></div>
{:else}<div class="device-grid">{#each $devices as device (device.id)}<button class="device-card" on:click={()=>openDevice(device)}><div class="device-top"><span class="device-symbol">▣</span><StatusDot status={device.status}/></div><div class="device-title">{device.hostname||device.device_id?.slice(0,8)||'Android device'}</div><div class="device-id">{device.device_id?.slice(0,18)||'—'}</div><div class="device-divider"></div><div class="device-stats"><span>IP <b>{device.tailscale_ip||'—'}</b></span><span>{ru?'Сайты':'Sites'} <b>{device.site_count||0}</b></span></div></button>{/each}</div>{/if}
<div class="section-header"><div><h2 class="section-title">{ru?'Последние сайты':'Recent sites'}</h2><p class="section-subtitle">{ru?'Приложения на подключённых устройствах':'Applications on connected devices'}</p></div><a href="/sites" class="view-link">{ru?'Все сайты':'All sites'} <span>→</span></a></div>
{#if allSites.length===0}<div class="empty compact-empty">{ru?'Здесь появятся сайты, размещённые на твоих устройствах.':'Sites hosted on your devices will appear here.'}</div>{:else}<div class="sites-table-wrap"><table class="sites-table"><thead><tr><th>{ru?'САЙТ':'SITE'}</th><th>{ru?'УСТРОЙСТВО':'DEVICE'}</th><th>RUNTIME</th><th>{ru?'ПОРТ':'PORT'}</th><th>{ru?'СТАТУС':'STATUS'}</th></tr></thead><tbody>{#each allSites.slice(0,6) as item (item.device_id+'-'+item.site.site_id)}<tr on:click={()=>openDevice({id:item.device_id})}><td><strong>{item.site.site_id}</strong></td><td>{item.device_name||'Android host'}</td><td>{item.site.runtime}</td><td class="mono">:{item.site.port}</td><td><StatusDot status={item.site.status}/></td></tr>{/each}</tbody></table></div>{/if}
<div class="overview-bottom-grid">
 <section><div class="section-header"><div><h2 class="section-title">{ru?'Последние развёртывания':'Recent deployments'}</h2><p class="section-subtitle">{ru?'Подтверждённые операции Agent':'Confirmed Agent operations'}</p></div><a href="/deployments" class="view-link">{ru?'Все операции →':'All operations →'}</a></div>
 {#if recentDeployments.length}<div class="activity-list">{#each recentDeployments as item}<div class="activity-row"><span class="activity-icon">{item.details?.ok===false?'!':'↗'}</span><span><strong>{item.action?.replaceAll('_',' ')||'Deployment'}</strong><small>{item.details?.site_id||item.device||'—'}</small></span><time>{item.created_at?formatDate(item.created_at):'—'}</time></div>{/each}</div>{:else}<div class="empty compact-empty">{ru?'Пока нет записей о развёртываниях.':'No deployment records yet.'}</div>{/if}
 </section>
 <section><div class="section-header"><div><h2 class="section-title">{ru?'Активность':'Activity'}</h2><p class="section-subtitle">{ru?'Последние события Control Plane':'Latest Control Plane events'}</p></div><a href="/logs" class="view-link">{ru?'Все журналы →':'All logs →'}</a></div>
 {#if activity.length}<div class="activity-list">{#each activity as item}<div class="activity-row"><span class="activity-icon">⌁</span><span><strong>{item.action?.replaceAll('_',' ')||'Event'}</strong><small>{item.device||'Control Plane'}</small></span><time>{item.created_at?formatDate(item.created_at):'—'}</time></div>{/each}</div>{:else}<div class="empty compact-empty">{ru?'Системных событий пока нет.':'No system events yet.'}</div>{/if}
 </section>
</div>
<div class="quick-actions"><strong>{ru?'Быстрые действия':'Quick actions'}</strong><a href="/projects">{ru?'＋ Новый проект':'＋ New project'}</a><button on:click={()=>showAddModal=true}>{ru?'▣ Подключить устройство':'▣ Connect device'}</button><a href="/deployments">↗ Развёртывания</a></div>
{/if}
<Modal open={showAddModal} title={ru?'Подключить устройство':'Connect device'} onClose={()=>showAddModal=false}><p class="modal-text">{ru?'Используй мастер подключения: он подскажет установку Agent, запросит WebSocket URL и отдельный pairing token из профиля.':'Use the guided connection flow. It explains Agent installation and asks for your Control Plane WebSocket URL and the separate pairing token from your profile.'}</p><p class="modal-text"><a class="pairing-link" href="/devices/connect">{ru?'Открыть мастер подключения →':'Open connection wizard →'}</a></p><svelte:fragment slot="footer"><Button on:click={()=>showAddModal=false}>{ru?'Закрыть':'Close'}</Button></svelte:fragment></Modal>
